create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','coordinator','contestant');
create type public.tournament_status as enum ('draft','published','registration_open','in_progress','completed','cancelled');
create type public.question_kind as enum ('calculation','non_calculation');
create type public.live_phase as enum ('idle','main_active','buzz_open','bonus_active','round_ended','completed');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null,school_name text,created_at timestamptz not null default now());
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null,primary key(user_id,role));
create table public.tournaments(id uuid primary key default gen_random_uuid(),name text not null,description text,max_participants integer not null check(max_participants>0),status public.tournament_status not null default 'draft',registration_opens_at timestamptz,registration_closes_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.contests(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,name text not null,status text not null default 'scheduled',rotation_index integer not null default 0 check(rotation_index>=0),created_at timestamptz not null default now());
create table public.rounds(id uuid primary key default gen_random_uuid(),contest_id uuid not null references public.contests(id) on delete cascade,name text not null,position integer not null check(position>0),unique(contest_id,position));
create table public.questions(id uuid primary key default gen_random_uuid(),round_id uuid not null references public.rounds(id) on delete cascade,position integer not null check(position>0),prompt text not null,kind public.question_kind not null,options jsonb not null check(jsonb_typeof(options)='array' and jsonb_array_length(options)=4),correct_option smallint not null check(correct_option between 0 and 3),created_at timestamptz not null default now(),unique(round_id,position));
create table public.registrations(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,contestant_id uuid not null references auth.users(id) on delete cascade,status text not null default 'registered' check(status in ('registered','withdrawn','approved','rejected')),created_at timestamptz not null default now(),unique(tournament_id,contestant_id));
create table public.contest_participants(id uuid primary key default gen_random_uuid(),contest_id uuid not null references public.contests(id) on delete cascade,contestant_id uuid not null references auth.users(id) on delete cascade,rotation_position integer not null check(rotation_position>0),total_score integer not null default 0,unique(contest_id,contestant_id),unique(contest_id,rotation_position));
create table public.contest_rooms(contest_id uuid primary key references public.contests(id) on delete cascade,phase public.live_phase not null default 'idle',active_question_id uuid references public.questions(id),active_contestant_id uuid references auth.users(id),bonus_winner_id uuid references auth.users(id),phase_started_at timestamptz,deadline_at timestamptz,version bigint not null default 0,updated_at timestamptz not null default now());
create table public.answer_attempts(id uuid primary key default gen_random_uuid(),contest_id uuid not null references public.contests(id) on delete cascade,question_id uuid not null references public.questions(id),contestant_id uuid not null references auth.users(id),answer_option smallint check(answer_option between 0 and 3),answer_type text not null check(answer_type in ('main','bonus')),is_correct boolean,points_awarded integer not null default 0,submitted_at timestamptz not null default now(),unique(contest_id,question_id,contestant_id,answer_type));
create table public.buzz_attempts(id uuid primary key default gen_random_uuid(),contest_id uuid not null references public.contests(id) on delete cascade,question_id uuid not null references public.questions(id),contestant_id uuid not null references auth.users(id) on delete cascade,received_at timestamptz not null default clock_timestamp(),accepted boolean not null default false,unique(contest_id,question_id,contestant_id));
create unique index buzz_one_winner_per_question on public.buzz_attempts(contest_id,question_id) where accepted;
create table public.contest_events(id bigint generated always as identity primary key,contest_id uuid not null references public.contests(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index participants_rotation_idx on public.contest_participants(contest_id,rotation_position);
create index questions_round_position_idx on public.questions(round_id,position);
create index events_contest_created_idx on public.contest_events(contest_id,created_at desc);
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.tournaments enable row level security; alter table public.contests enable row level security; alter table public.rounds enable row level security; alter table public.questions enable row level security; alter table public.registrations enable row level security; alter table public.contest_participants enable row level security; alter table public.contest_rooms enable row level security; alter table public.answer_attempts enable row level security; alter table public.buzz_attempts enable row level security; alter table public.contest_events enable row level security;
create policy "read own profile" on public.profiles for select to authenticated using((select auth.uid())=id);
create policy "insert own profile" on public.profiles for insert to authenticated with check((select auth.uid())=id);
create policy "update own profile" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
create policy "read own registrations" on public.registrations for select to authenticated using((select auth.uid())=contestant_id);
create policy "read own participant record" on public.contest_participants for select to authenticated using((select auth.uid())=contestant_id);
-- Intentionally no client write policies for scores, answer keys, roles, live state or buzz winner. Add authenticated server RPCs and role-specific read policies before launch.
